"""Adroit pen, two target orientations in a row: pose sequencing, checked on a private copy of the plant.

Control law
-----------
The action is piecewise constant: a "pose" (24 joint set points) is held for some tens of steps, then the next one.
Nothing is learned and nothing is fed back joint by joint. Instead the controller keeps an exact copy of the plant
(the package's own model, stepped with the actions already returned; the reset state is the same in every episode
and the simulation is deterministic, so the copy is in the plant's state at every step) and uses it as a predictor:
candidate poses are rolled out in the copy before one is sent to the hand.

1. Hub. From the reset state the hand takes one fixed pose (HUB) for HUB_STEPS steps. It props the pen up on the
   fingers; from that state one further pose change reaches nearly every target orientation.
2. First target: table look-up. LIB holds poses found offline by a derivative-free search on the simulator. At
   start-up each is rolled out once from the hub state and its pen-axis trajectory is stored. A target is served by a
   library pose whose trajectory holds it (cosine > 0.95, centre in the ball, 25 consecutive steps). When several
   do, the one that leaves the pen most movable afterwards is taken (MOB, measured offline: the share of orientations
   a single further pose change comes close to from that pose's held state).
3. Later targets: best-first search from the true state. Candidates are held for PHASE_STEPS steps in the copy:
   poses of a pool (POOL) whose nominal held orientation (NOM) is closest to the target, and, once the pen is within
   NEAR_COS of the target, random variations of the pose being held. A candidate that holds the target for 25 steps
   ends the search. Otherwise the candidate that leaves the pen best aligned becomes the next phase of the plan and
   the search goes on from its end state, until the target's 200 steps are used up. If nothing is found, a second
   attempt runs with shorter phases and another candidate order.

Gains
-----
HUB_STEPS          steps the hub pose is held from reset
PHASE_STEPS        steps a candidate pose is held in the search; EARLY_STEPS: a candidate may be cut here already
                   when the pen is as well aligned as at the end of the phase (leaves time for more phases)
RETRY_*            the same two for the second attempt
CANDIDATES         candidates rolled out per phase
MAX_SHOTS          most roll-outs per attempt (one costs about 10 ms)
NEAR_COS           alignment (cosine) from which half of the candidates are variations of the held pose
SIGMA              size of those variations, in action units (set-point half ranges)
MOB_W, MARGIN_W    first target: weights of "leaves the pen movable" and of "ends well inside the target cone in a
                   steady hold" among the library poses that reach the target
EPISODE_BUDGET     seconds of search time earned per episode (START_BUDGET at the start, at most MAX_BUDGET banked,
                   at most SEARCH_CAP and at most half of the account in one search); a search stops early when
                   its share is used up (the first batch of candidates is always rolled out), so the
                   computing time per episode is bounded on any machine
"""

import base64
import time

import mujoco
import numpy as np

# the task's own numbers: hold count, steps per target, alignment and distance of the success condition
HOLD, TMAX, COS_OK, BALL_R = 25, 200, 0.95, 0.075

HUB_STEPS = 60
PHASE_STEPS, EARLY_STEPS = 45, 25
RETRY_PHASE_STEPS, RETRY_EARLY_STEPS = 30, 15
CANDIDATES = 40
MAX_SHOTS = 320
NEAR_COS = 0.8
SIGMA = 0.2
MOB_W, MARGIN_W = 1.0, 0.2
EPISODE_BUDGET, START_BUDGET, MAX_BUDGET, SEARCH_CAP = 1.6, 12.0, 30.0, 8.0
FOREVER = 10 ** 6


def _decode(text, width):
    return np.frombuffer(base64.b64decode(text), dtype=np.float16).astype(float).reshape(-1, width)


# poses (actions in [-1, 1], float16, base64): hub pose, first-target library with its launch-pad scores, search pool
# with the pen axis each pool pose ends at when applied from the hub state
HUB = _decode("ALwAvHAqpDvHu3gx26Mmu0+2ADxuOie6XDi4pa+wY7TVuM+0g6/WuWQ0BzVFthkm", 24)[0]
LIB = _decode("", 24)
MOB = _decode("", 1)[:, 0]
POOL = _decode("", 24)
NOM = _decode("", 3)


class _Mirror:
    """A private copy of the plant: same model, same integrator, stepped with the same actions."""

    def __init__(self):
        from hl_control.envs.adroit import AdroitConfig, AdroitEnv
        self.env = AdroitEnv(AdroitConfig(task="pen", mode="chain", chain_targets=2, seed=0))
        self.m, self.d, sim = self.env.model, self.env.data, self.env.sim
        self.mean, self.rng = np.array(sim.act_mean), np.array(sim.act_rng)
        self.obj, self.top, self.bottom = sim.obj_body_id, sim.obj_t_site_id, sim.obj_b_site_id
        sim.reset(seed=0)
        self.ball = self.d.site_xpos[sim.eps_ball_site_id].copy()
        self.spec = mujoco.mjtState.mjSTATE_INTEGRATION
        self.s0 = self.get()

    def get(self):
        s = np.zeros(mujoco.mj_stateSize(self.m, self.spec))
        mujoco.mj_getState(self.m, self.d, s, self.spec)
        return s

    def set(self, s):
        mujoco.mj_setState(self.m, self.d, s, self.spec)

    def step(self, a):
        """One control step, as the environment does it."""
        self.d.ctrl[:] = self.mean + np.clip(a, -1.0, 1.0) * self.rng
        mujoco.mj_step(self.m, self.d, nstep=5)

    def pen(self):
        """Pen centre and unit axis as the environment reads them after a step."""
        ax = self.d.site_xpos[self.top] - self.d.site_xpos[self.bottom]
        return self.d.xpos[self.obj].copy(), ax / np.linalg.norm(ax)


class _Controller:
    def __init__(self):
        self.mir = mir = _Mirror()
        mir.set(mir.s0)
        for _ in range(HUB_STEPS):
            mir.step(HUB)
        self.hub_state = mir.get()
        # table: pen trajectory of every library pose from the hub state
        n, T = len(LIB), TMAX - HUB_STEPS
        P, self.A = np.zeros((n, T, 3)), np.zeros((n, T, 3))
        for i in range(n):
            mir.set(self.hub_state)
            for t in range(T):
                mir.step(LIB[i])
                P[i, t], self.A[i, t] = mir.pen()
                if P[i, t, 2] < BALL_R:
                    P[i, t:], self.A[i, t:] = P[i, t], self.A[i, t]
                    break
        self.inball = (np.linalg.norm(P - mir.ball, axis=2) < BALL_R) & (np.cumsum(P[:, :, 2] < BALL_R, axis=1) == 0)
        self.final = self.A[:, -1]
        self.steady = self.inball[:, -1] & (np.einsum("ltk,lk->lt", self.A[:, -40:], self.final).min(axis=1) > 0.999)
        self.stats = dict(shots=0, plan_time=0.0, fail1=0, fail2=0, retry=0, cut=0, episodes=0, mismatch=0)
        self.credit = START_BUDGET
        self.plan, self.seg, self.k, self.tidx = [(HUB, FOREVER)], 0, 0, -1

    # ----- first target: the table -----

    def table_reach(self, target):
        """Step (counted from the hub state) at which each library pose has held the target for HOLD steps, or -1."""
        ok = (self.A @ target > COS_OK) & self.inball
        run = np.zeros(len(LIB), dtype=int)
        out = -np.ones(len(LIB), dtype=int)
        for t in range(ok.shape[1]):
            run = np.where(ok[:, t], run + 1, 0)
            hit = (run >= HOLD) & (out < 0)
            out[hit] = t + 1
        return out

    def plan_first(self, target):
        reach = self.table_reach(target)
        score = (reach > 0) * 4.0 + MOB_W * MOB + MARGIN_W * (self.final @ target + self.steady)
        best = int(np.argsort(-score)[0])
        if reach[best] > 0:
            return [(HUB, HUB_STEPS), (LIB[best], FOREVER)]
        self.stats["fail1"] += 1                      # no table entry: search from the hub state instead
        return [(HUB, HUB_STEPS)] + self.plan_next(self.hub_state, target, TMAX - HUB_STEPS, HUB)

    # ----- later targets: search in the copy -----

    def probe(self, s, pose, target, run, horizon, limit, early=0):
        """Hold `pose` from state s for `horizon` steps (longer while the success run is growing, at most `limit`).
        Returns (reached, steps used, score, end state, success run at the end). With `early` > 0 the state after
        `early` steps is returned instead when the pen is already as well aligned there as at the horizon."""
        mir = self.mir
        mir.set(s)
        t, c, first = 0, -1.0, None
        while t < limit:
            mir.step(pose)
            t += 1
            pos, ax = mir.pen()
            if pos[2] < BALL_R:                       # dropped
                return False, t, -2.0, None, 0
            inb = np.linalg.norm(pos - mir.ball) < BALL_R
            c = float(ax @ target)
            run = run + 1 if (c > COS_OK and inb) else 0
            if run >= HOLD:
                return True, t, 2.0, None, run
            if t == early and inb:
                first = (False, t, c + 0.002 * run, mir.get(), run)
            if t >= horizon and run == 0:
                break
        if not inb:
            return first if first is not None else (False, t, -1.0, None, 0)
        last = (False, t, c + 0.002 * run, mir.get(), run)
        if first is not None and first[2] >= last[2] - 0.005:
            return first
        return last

    def plan_next(self, s, target, steps, pose):
        """Plan from the true state s, where `pose` is being held and `steps` steps are left for the target."""
        t0 = time.perf_counter()
        deadline = t0 + min(max(0.5 * self.credit, 0.3), SEARCH_CAP)   # never more than half of the account
        plan, found = self.search(s, target, steps, pose, PHASE_STEPS, EARLY_STEPS, 12345, 0, deadline, CANDIDATES)
        if not found and time.perf_counter() < deadline:
            self.stats["retry"] += 1
            plan2, found = self.search(s, target, steps, pose, RETRY_PHASE_STEPS, RETRY_EARLY_STEPS, 777, 7, deadline, 0)
            if found:
                plan = plan2
        if not found:
            self.stats["fail2"] += 1
        used = time.perf_counter() - t0
        self.credit -= used
        self.stats["plan_time"] += used
        return plan

    def search(self, s, target, steps, pose, H, early, seed, shift, deadline, free_shots):
        """Best-first search over pose sequences. Returns (plan as [(pose, steps), ...], found). The first
        `free_shots` roll-outs are made whatever the clock says; after them the search stops at `deadline`."""
        rng = np.random.default_rng(seed)
        order = list(np.argsort(-(NOM @ target)))     # pool poses, nominal held axis closest to the target first
        order = order[shift:] + order[:shift]
        mir = self.mir
        mir.set(s)
        mujoco.mj_kinematics(mir.m, mir.d)
        cur = float(mir.pen()[1] @ target)            # alignment now
        plan, used, run, found, shots, stall, ptr = [], 0, 0, False, 0, 0, 0
        while shots < MAX_SHOTS:
            left = steps - used
            if left < HOLD:
                break
            n_pool = CANDIDATES // 2 if cur > NEAR_COS else CANDIDATES
            cands = [POOL[j] for j in order[ptr:ptr + n_pool]]
            ptr += n_pool
            if ptr >= len(order):
                ptr = 0
            while len(cands) < CANDIDATES:            # local variations of the pose being held
                sig = SIGMA * rng.choice([0.4, 1.0, 2.0])
                mask = rng.random(24) < rng.choice([0.3, 1.0])
                cands.append(np.clip(pose + sig * rng.normal(size=24) * mask, -1.0, 1.0))
            best = (-9.0, None, None, 0, 0)
            for c in cands:
                if shots >= free_shots and time.perf_counter() > deadline:
                    self.stats["cut"] += 1
                    break
                ok, t, score, s_end, r_end = self.probe(s, c, target, run, min(H, left), left, early)
                shots += 1
                if ok:
                    plan.append((c, FOREVER))
                    found = True
                    break
                if score > best[0]:
                    best = (score, c, s_end, r_end, t)
            if found:
                break
            out_of_time = shots >= free_shots and time.perf_counter() > deadline
            if best[2] is not None and (best[0] > cur + 0.01 or stall >= 1 or out_of_time):
                plan.append((best[1], best[4]))       # commit the best candidate as the next phase
                s, run, used, pose, cur, stall, ptr = best[2], best[3], used + best[4], best[1], best[0], 0, 0
            else:
                stall += 1                            # nothing better than staying: another batch from the same state
            if out_of_time:
                break
        if not plan:
            plan = [(pose, FOREVER)]
        self.stats["shots"] += shots
        return plan, found

    # ----- one control step -----

    def __call__(self, obs):
        o = np.asarray(obs["observation"], dtype=float)
        step = int(obs["step"])
        if step == 0:
            self.mir.set(self.mir.s0)
            self.tidx = -1
            self.credit = min(MAX_BUDGET, self.credit + EPISODE_BUDGET)
            self.stats["episodes"] += 1
        else:
            self.mir.step(np.asarray(obs["last_action"], dtype=float))
            if np.abs(self.mir.d.qpos[:24] - o[:24]).max() > 1e-7:
                self.stats["mismatch"] += 1
        target = o[36:39] / max(np.linalg.norm(o[36:39]), 1e-9)
        tidx = int(obs.get("target_index", 0))
        if tidx != self.tidx:                         # a new target: plan for it
            self.tidx = tidx
            s_now = self.mir.get()
            held = np.asarray(obs["last_action"], dtype=float)
            try:
                if step == 0:
                    self.plan = self.plan_first(target)
                else:
                    self.plan = self.plan_next(s_now, target, TMAX - int(obs.get("target_step", 0)), held)
            except Exception:                         # never fail the run on a planning error: keep the pose
                self.plan = [(held, FOREVER)]
            self.mir.set(s_now)
            self.seg, self.k = 0, 0
        while self.seg + 1 < len(self.plan) and self.k >= self.plan[self.seg][1]:
            self.seg += 1
            self.k = 0
        self.k += 1
        return np.array(self.plan[self.seg][0], dtype=float)


_CTL = None


def controller(obs: dict) -> np.ndarray:
    global _CTL
    if _CTL is None:
        _CTL = _Controller()
    return _CTL(obs)
